const body = $('Check webhook').first().json.body;
// team baseline: only empty values (written in a hurry last month)
const rows = body.items.map((r) => {
  const errors = [];
  if (!r.title) errors.push('title_missing');
  if (!r.answer) errors.push('answer_missing');
  if (!r.keywords || r.keywords.length === 0) errors.push('keywords_missing');
  return { id: String(r.id ?? ''), ok: errors.length === 0, errors, warnings: [] };
});
const codes = {};
for (const row of rows) for (const e of row.errors) codes[e] = (codes[e] ?? 0) + 1;
const valid = rows.filter((r) => r.ok).length;
return [{ json: { batch: body.batch ?? '', total: rows.length, valid, invalid: rows.length - valid, rows, codes } }];
